pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let stream_progress = step_index as f64 / total_items as f64;

    // Penalize bins that are almost full but can still fit more items
    if bin_capacity - item_size < 10 { 
        score += 3.5; 
    }

    // Reward bins with very small residuals
    if bin_residual <= 5 { 
        score -= 0.9 * (bin_residual as f64 / 5.0); 
    }

    // Bonus for bins with multiple fitting items
    if fitting_bins_count > 3 { 
        score += 0.9; 
    }

    // Penalize large mean residuals relative to bin capacity
    let residual_diff = (mean_residual - bin_residual as f64) / (bin_capacity as f64 - mean_residual);
    if residual_diff > 0.1 {
        score -= 0.8 * residual_diff;
    }

    // Reward for next item size being smaller than post-residual
    if next_item_size < post_residual { 
        score += 0.35; 
    }

    // Penalize open bins with very small residuals when only one bin is left
    if open_bins_count == 1 && bin_residual < 20 { 
        score -= 1.2; 
    }

    // Adjust score based on stream progress and post-residual
    let score = score * 0.7 + ((-post_residual as f64 * (1.0 + 3.5 * stream_progress)) as f64) * 0.3;

    score
}

