pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let stream_progress = step_index as f64 / total_items as f64;

    // Penalize if bin capacity is close to being full
    if bin_capacity - item_size < 15 { 
        score += 2.5; 
    }

    // Reward if bin residual is low
    if bin_residual <= 5 { 
        score -= 0.5 * (bin_residual as f64 / 5.0); 
    }

    // Reward if there are many fitting bins available
    if fitting_bins_count > 3 { 
        score += 0.7; 
    }

    // Penalize large discrepancies between mean residual and current bin residual
    score -= 0.5 * ((mean_residual - bin_residual as f64) / (bin_capacity as f64 - mean_residual));

    // Reward if the next item is smaller than post-residual
    if next_item_size < post_residual { 
        score += 0.4; 
    }

    // Penalize if only one open bin and residual is low
    if open_bins_count == 1 && bin_residual < 20 { 
        score -= 0.7; 
    }

    // Adjust score based on stream progress
    let score = score * 0.8 + ((-post_residual as f64 * (1.0 + 5.0 * stream_progress)) as f64) * 0.2;

    // Incorporate post-residual and remaining capacity for better compaction
    let score = score * 0.9 + ((post_residual + (bin_capacity - bin_residual).min(next_item_size)) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
